/* days-32-38.js: lesson content for Days 32 to 38 (read by day.html). Each day has 6 blocks of 30 minutes. */
(function(){
var D = (window.DAYS = window.DAYS || {});
var CHK = "der = blue, die = red, das = green. Always learn the article with the noun.";

/* ================= DAY 32 ================= */
D[32] = {title: "Regular verbs in the Präteritum", level: "Level A2",
intro: "Today you learn how regular verbs look in the past (wohnte, arbeitete, spielte). You need them to read stories and to write about family and the past.",
blocks: [
{title: "20 new words", goal: "Goal: say what each word means. Cover the English column and test yourself. Do this 2 times.", parts: [
 {t: "words", rows: [["der Großvater","grandfather"],["die Großmutter","grandmother"],["die Eltern","parents (plural)"],["die Kindheit","childhood"],["das Dorf","village"],["die Schule","school"],["der Garten","garden"],["die Geschichte","story, history"],["das Feld","field"],["wohnen","to live (in a place)"],["lernen","to learn"],["spielen","to play"],["arbeiten","to work"],["kaufen","to buy"],["kochen","to cook"],["besuchen","to visit"],["erzählen","to tell"],["leben","to live, to be alive"],["lachen","to laugh"],["hören","to hear, to listen"]]},
 {t: "p", h: CHK}]},
{title: "Regular verbs in the Präteritum", goal: "Goal: recognise and build the Präteritum of regular verbs: stem + -te + ending.", parts: [
 {t: "key", h: "<b>Rule:</b> take the stem (wohn-), add <b>-te</b>, then the ending. <i>ich</i> and <i>er/sie/es</i> always have the same form."},
 {t: "table", head: ["","wohnen","arbeiten"], de: [1,2], rows: [["ich","wohnte","arbeitete"],["du","wohntest","arbeitetest"],["er / sie / es","wohnte","arbeitete"],["wir","wohnten","arbeiteten"],["ihr","wohntet","arbeitetet"],["sie / Sie","wohnten","arbeiteten"]]},
 {t: "key", h: "<b>Extra -e:</b> if the stem ends in -t or -d (arbeiten, warten, reden), add an e: arbeitete, wartete, redete."},
 {t: "h", h: "Examples, read aloud"},
 {t: "ex", items: [["Meine Großeltern wohnten in einem kleinen Dorf.","My grandparents lived in a small village."],["Mein Vater arbeitete auf dem Feld.","My father worked in the field."],["Wir spielten jeden Tag im Garten.","We played in the garden every day."],["Meine Mutter kochte jeden Abend.","My mother cooked every evening."],["Ich lernte schon früh lesen.","I learned to read early."],["Wir besuchten jeden Sonntag meine Oma.","We visited my grandma every Sunday."]]},
 {t: "key", h: "<b>Speaking or writing?</b> In everyday speech you mostly use the Perfekt for these verbs (you learn it in week 2). The Präteritum of regular verbs is what you read in stories, news and letters, and what you write in formal texts. Today, learn to recognise it and to write it."}]},
{title: "Practice: regular verbs", goal: "Goal: write the forms without looking at the table. Write on paper first, then check.", parts: [
 {t: "q", title: "Practice 1: fill the gap", items: ["1. Mein Großvater ___ in einem Dorf. (wohnen)","2. Wir ___ im Garten Fußball. (spielen)","3. Du ___ gestern sehr lange. (arbeiten)","4. Meine Eltern ___ jeden Tag frisches Brot. (kaufen)","5. Ihr ___ sehr laut. (lachen)","6. Ich ___ als Kind schnell. (lernen)","7. Die Kinder ___ gern Musik. (hören)","8. Sie ___ auf den Bus. (warten)"], ans: "1. wohnte · 2. spielten · 3. arbeitetest · 4. kauften · 5. lachtet · 6. lernte · 7. hörten · 8. wartete"},
 {t: "q", title: "Practice 2: Perfekt to Präteritum (written style)", items: ["1. Er hat im Garten gearbeitet.","2. Wir haben Kaffee gekocht.","3. Sie hat ihre Tante besucht.","4. Ich habe viel gelernt.","5. Die Kinder haben gelacht.","6. Meine Mutter hat eine Geschichte erzählt."], ans: "1. Er arbeitete im Garten. · 2. Wir kochten Kaffee. · 3. Sie besuchte ihre Tante. · 4. Ich lernte viel. · 5. Die Kinder lachten. · 6. Meine Mutter erzählte eine Geschichte."},
 {t: "q", title: "Practice 3: say in German (aloud, then on paper)", items: ["1. My grandfather lived in a village.","2. We played in the garden.","3. She worked a lot.","4. I visited my grandma."], ans: "1. Mein Großvater wohnte in einem Dorf. · 2. Wir spielten im Garten. · 3. Sie arbeitete viel. · 4. Ich besuchte meine Oma."}]},
{title: "Dialogue: where did you live?", goal: "Goal: understand a spoken conversation about the past. In speech people use the Perfekt (habe gewohnt) plus war and hatte. You learn the Perfekt step by step in week 2, so today just read it and say it aloud.", parts: [
 {t: "text", de: "Anna: Wo hast du früher gewohnt?<br>Murat: Ich habe in einem Dorf gewohnt. Wir hatten ein Haus mit einem großen Garten.<br>Anna: Und was hast du dort gemacht?<br>Murat: Ich habe jeden Tag im Garten gespielt. Mein Vater hat auf dem Feld gearbeitet, und meine Mutter war zu Hause und hat gekocht.<br>Anna: Das klingt schön.<br>Murat: Ja, es war eine schöne Zeit.", en: "Anna: Where did you live before? Murat: I lived in a village. We had a house with a big garden. Anna: And what did you do there? Murat: I played in the garden every day. My father worked in the field, and my mother was at home and cooked. Anna: That sounds nice. Murat: Yes, it was a nice time.", qs: ["1. Wo hat Murat früher gewohnt?","2. Was hatte die Familie?","3. Wo hat Murats Vater gearbeitet?"], ans: "1. In einem Dorf. · 2. Ein Haus mit einem großen Garten. · 3. Auf dem Feld."},
 {t: "p", h: "Read the dialogue aloud twice. Then cover Murat's lines and answer the questions about your own childhood."}]},
{title: "Read: Opas Kindheit", goal: "Goal: understand a short written story in the Präteritum. Follow the steps: listen, read, answer, find the verbs.", parts: [
 {t: "text", title: "Opas Kindheit", de: "Mein Großvater wohnte als Kind in einem kleinen Dorf. Sein Vater arbeitete auf dem Feld, und seine Mutter kochte jeden Tag für die ganze Familie. Die Kinder spielten nach der Schule im Garten. Sie lernten viel, aber sie lachten auch oft. Am Sonntag besuchten sie die Großmutter. Sie erzählte immer lange Geschichten, und alle hörten gern zu. Mein Großvater sagt heute: Das war eine schöne Zeit.", en: "My grandfather lived in a small village as a child. His father worked in the field, and his mother cooked every day for the whole family. The children played in the garden after school. They learned a lot, but they also laughed often. On Sunday they visited their grandmother. She always told long stories, and everyone listened gladly. My grandfather says today: That was a nice time.", qs: ["1. Wo wohnte der Großvater als Kind?","2. Was machte sein Vater?","3. Was machten die Kinder nach der Schule?","4. Wann besuchten sie die Großmutter?"], ans: "1. In einem kleinen Dorf. · 2. Er arbeitete auf dem Feld. · 3. Sie spielten im Garten. · 4. Am Sonntag.", note: "Now find every verb that ends in -te or -ten: wohnte, arbeitete, kochte, spielten, lernten, lachten, besuchten, erzählte, hörten. Note: hörten ... zu is the verb zuhören (to listen), split into two parts."}]},
{title: "Say it aloud and write", parts: [
 {t: "say", title: "Part A: speak (15 min)", goal: "Press Hear it, then say each sentence 3 times out loud, as fast as the voice.", items: ["Meine Großeltern wohnten in einem Dorf.","Mein Vater arbeitete viel.","Wir spielten im Garten.","Meine Mutter kochte jeden Tag.","Ich lernte früh lesen.","Wir besuchten oft meine Oma.","Die Kinder lachten laut.","Damals hatten wir kein Auto, aber wir waren glücklich."]},
 {t: "write", title: "Part B: write (15 min), today's homework", goal: "Write 8 sentences about your grandparents or your childhood. Use at least 5 regular verbs in the Präteritum, and war, hatte or a modal verb at least once.", starters: ["Meine Großeltern wohnten ...","Mein Vater arbeitete ...","Als Kind spielte ich ...","Meine Mutter kochte ..."], model: "Meine Großeltern wohnten in einem kleinen Haus. Mein Großvater arbeitete in einer Fabrik. Meine Großmutter kochte jeden Tag für die Familie. Als Kind besuchte ich sie oft. Wir spielten im Garten und lachten viel. Mein Opa erzählte lustige Geschichten. Damals hatten wir wenig Geld, aber wir waren glücklich. Ich musste nie lange warten, wenn ich Hunger hatte."},
 {t: "q", title: "Final check (3 min)", items: ["Without looking above, say in German: 1. We lived in a village. 2. My father worked a lot. 3. The children played in the garden. 4. She cooked every day. 5. I visited my aunt."], ans: "1. Wir wohnten in einem Dorf. · 2. Mein Vater arbeitete viel. · 3. Die Kinder spielten im Garten. · 4. Sie kochte jeden Tag. · 5. Ich besuchte meine Tante."}]}
]};

/* ================= DAY 33 ================= */
D[33] = {title: "Irregular verbs in the Präteritum", level: "Level A2",
intro: "Today you learn the 15 most useful irregular verbs in the Präteritum (ging, kam, sah, fuhr, fand ...). They appear in almost every written German text, so learn them as pairs.",
blocks: [
{title: "20 new words", goal: "Goal: say what each word means. Cover the English column and test yourself. Do this 2 times.", parts: [
 {t: "words", rows: [["der Beruf","profession, job"],["das Leben","life"],["die Hochzeit","wedding"],["die Stadt","city, town"],["der Anfang","beginning"],["das Ende","end"],["die Arbeit","work"],["das Geld","money"],["aufwachsen","to grow up"],["heiraten","to marry"],["umziehen","to move (house)"],["finden","to find"],["treffen","to meet"],["bringen","to bring"],["denken","to think"],["wissen","to know (a fact)"],["sprechen","to speak"],["nehmen","to take"],["bleiben","to stay"],["schreiben","to write"]]},
 {t: "p", h: CHK}]},
{title: "15 irregular verbs", goal: "Goal: know these 15 verbs as pairs: infinitive and Präteritum. The Perfekt column is for next week, just look at it.", parts: [
 {t: "table", head: ["Infinitive","Präteritum (ich / er)","Perfekt (er ...)"], de: [1], rows: [["gehen","ging","ist gegangen"],["kommen","kam","ist gekommen"],["sehen","sah","hat gesehen"],["essen","aß","hat gegessen"],["fahren","fuhr","ist gefahren"],["geben","gab","hat gegeben"],["nehmen","nahm","hat genommen"],["bleiben","blieb","ist geblieben"],["finden","fand","hat gefunden"],["sprechen","sprach","hat gesprochen"],["treffen","traf","hat getroffen"],["schreiben","schrieb","hat geschrieben"],["bringen","brachte","hat gebracht"],["denken","dachte","hat gedacht"],["wissen","wusste","hat gewusst"]]},
 {t: "key", h: "<b>Rule:</b> irregular verbs change their stem and have <b>no -te</b>. Endings: ich -, du -st, er -, wir -en, ihr -t, sie -en. Example: ging, gingst, ging, gingen, gingt, gingen. The last three verbs (bringen, denken, wissen) change the stem <i>and</i> add -te."},
 {t: "h", h: "Examples, read aloud"},
 {t: "ex", items: [["Mein Opa ging jeden Tag zu Fuß zur Arbeit.","My grandpa walked to work every day."],["Meine Oma kam aus einer kleinen Stadt.","My grandma came from a small town."],["Sie trafen sich auf einer Hochzeit.","They met at a wedding."],["Er fuhr mit dem Zug nach Berlin.","He went to Berlin by train."],["Ich wusste nicht, wo er wohnte.","I did not know where he lived."]]}]},
{title: "Practice: irregular verbs", goal: "Goal: write the forms without looking at the table. Write on paper first, then check.", parts: [
 {t: "q", title: "Practice 1: fill the gap", items: ["1. Wir ___ gestern ins Kino. (gehen)","2. Er ___ mir einen Brief. (schreiben)","3. Sie ___ ihre Freundin am Bahnhof. (treffen)","4. Ich ___ nicht, dass du hier warst. (wissen)","5. Meine Tante ___ aus Hamburg. (kommen)","6. Du ___ zu lange im Büro. (bleiben)","7. Wir ___ viel Obst. (essen)","8. Ihr ___ mir das Geld. (geben)","9. Die Kinder ___ mit dem Bus. (fahren)","10. Er ___ an seine Familie. (denken)"], ans: "1. gingen · 2. schrieb · 3. traf · 4. wusste · 5. kam · 6. bliebst · 7. aßen · 8. gabt · 9. fuhren · 10. dachte"},
 {t: "q", title: "Practice 2: present to Präteritum (a story from the past)", items: ["1. Sie nimmt den Zug.","2. Wir sehen einen Film.","3. Er bringt Blumen mit.","4. Ich finde meinen Schlüssel nicht.","5. Sie spricht mit dem Chef."], ans: "1. Sie nahm den Zug. · 2. Wir sahen einen Film. · 3. Er brachte Blumen mit. · 4. Ich fand meinen Schlüssel nicht. · 5. Sie sprach mit dem Chef."}]},
{title: "Dialogue: interview with Oma", goal: "Goal: understand a spoken conversation about a life story. Spoken German uses the Perfekt (bin aufgewachsen, haben geheiratet). Recognise it today, you will learn it next week.", parts: [
 {t: "text", de: "Enkel: Oma, wo bist du aufgewachsen?<br>Oma: Ich bin in einem Dorf aufgewachsen. Wir hatten ein Haus mit Garten.<br>Enkel: Und wie hast du Opa kennengelernt?<br>Oma: Auf einer Hochzeit. Er war damals sehr schüchtern, aber er hat mich zum Tanzen eingeladen.<br>Enkel: Wann habt ihr geheiratet?<br>Oma: Ein Jahr später. Wir sind dann in die Stadt gezogen, denn Opa hat dort eine Arbeit gefunden.", en: "Grandson: Grandma, where did you grow up? Grandma: I grew up in a village. We had a house with a garden. Grandson: And how did you meet Grandpa? Grandma: At a wedding. He was very shy back then, but he invited me to dance. Grandson: When did you get married? Grandma: A year later. Then we moved to the city, because Grandpa found a job there.", qs: ["1. Wo ist Oma aufgewachsen?","2. Wo haben sie sich kennengelernt?","3. Warum sind sie in die Stadt gezogen?"], ans: "1. In einem Dorf. · 2. Auf einer Hochzeit. · 3. Weil Opa dort eine Arbeit gefunden hat."}]},
{title: "Read: my grandparents' life", goal: "Goal: understand a written life story full of irregular verbs. Follow the steps: listen, read, answer, find the verbs.", parts: [
 {t: "text", title: "Das Leben meiner Großeltern", de: "Meine Großmutter kam aus einer kleinen Stadt im Norden. Mein Großvater fuhr als junger Mann mit dem Zug in ihre Stadt, denn er fand dort Arbeit. Auf einer Hochzeit trafen sie sich zum ersten Mal. Er sprach kaum, aber sie lachte viel. Sie schrieben sich viele Briefe. Ein Jahr später heirateten sie. Sie blieben in der Stadt und nahmen eine kleine Wohnung. Meine Mutter kam zwei Jahre später zur Welt.", en: "My grandmother came from a small town in the north. As a young man my grandfather went by train to her town, because he found work there. They met for the first time at a wedding. He hardly spoke, but she laughed a lot. They wrote each other many letters. A year later they got married. They stayed in the city and took a small flat. My mother was born two years later.", qs: ["1. Woher kam die Großmutter?","2. Warum fuhr der Großvater in ihre Stadt?","3. Wo trafen sie sich?","4. Wann heirateten sie?"], ans: "1. Aus einer kleinen Stadt im Norden. · 2. Er fand dort Arbeit. · 3. Auf einer Hochzeit. · 4. Ein Jahr später.", note: "Find all irregular verbs: kam, fuhr, fand, trafen, sprach, schrieben, blieben, nahmen. Note: kam zur Welt means was born."}]},
{title: "Say it aloud and write", parts: [
 {t: "say", title: "Part A: speak (15 min)", goal: "Press Hear it, then say each sentence 3 times out loud, as fast as the voice.", items: ["Meine Oma kam aus einer kleinen Stadt.","Mein Opa fuhr mit dem Zug nach Berlin.","Sie trafen sich auf einer Hochzeit.","Er sprach kaum, aber sie lachte viel.","Wir blieben in der Stadt.","Ich wusste nicht, wo er war.","Sie schrieben sich viele Briefe.","Er fand endlich eine Arbeit."]},
 {t: "write", title: "Part B: write (15 min), today's homework", goal: "Write 8 sentences about the life of a family member (a grandparent, a parent or an aunt). Use at least 5 irregular verbs from the table in the Präteritum.", starters: ["Mein Onkel kam aus ...","Er fand eine Arbeit in ...","Sie trafen sich ...","Danach blieben sie ..."], model: "Mein Vater kam aus einem kleinen Dorf. Er ging dort zur Schule und fuhr jeden Tag mit dem Bus. Mit 20 Jahren fand er eine Arbeit in der Stadt. Dort traf er meine Mutter. Sie sprachen lange miteinander und schrieben sich Briefe. Zwei Jahre später heirateten sie. Sie nahmen eine kleine Wohnung und blieben viele Jahre dort. Ich wusste als Kind nicht, wie schwer das Leben war."},
 {t: "q", title: "Final check (3 min)", items: ["Without looking above, say in German: 1. He came from Hamburg. 2. We went to the cinema. 3. She wrote a letter. 4. They stayed at home. 5. I did not know that."], ans: "1. Er kam aus Hamburg. · 2. Wir gingen ins Kino. · 3. Sie schrieb einen Brief. · 4. Sie blieben zu Hause. · 5. Ich wusste das nicht."}]}
]};

/* ================= DAY 34 ================= */
D[34] = {title: "Time, appointments and a day in the office", level: "Level A2",
intro: "Today is office German: telling the time the German way, making and moving appointments, and writing a short formal email. You need this for any job, and for the Ausbildung.",
blocks: [
{title: "20 new words", goal: "Goal: say what each word means. Cover the English column and test yourself. Do this 2 times.", parts: [
 {t: "words", rows: [["der Termin","appointment"],["die Besprechung","meeting"],["das Büro","office"],["der Kollege","colleague (male)"],["der Chef","boss"],["die Pause","break"],["die Mittagspause","lunch break"],["der Feierabend","end of the working day"],["der Kalender","calendar"],["die Uhr","clock, o'clock"],["die Stunde","hour"],["die Verspätung","delay"],["pünktlich","on time"],["erreichbar","reachable"],["vereinbaren","to arrange, to agree on"],["verschieben","to postpone, to move"],["absagen","to cancel"],["anfangen","to begin"],["dauern","to last"],["zurückrufen","to call back"]]},
 {t: "p", h: CHK}]},
{title: "Telling the time", goal: "Goal: say and understand times the way Germans do. Official times (24 hours) are for timetables and offices. Spoken times are for daily life.", parts: [
 {t: "table", head: ["Time","Official (24 h)","Spoken"], de: [1,2], rows: [["8:00","acht Uhr","acht Uhr"],["8:15","acht Uhr fünfzehn","Viertel nach acht"],["8:30","acht Uhr dreißig","halb neun"],["8:45","acht Uhr fünfundvierzig","Viertel vor neun"],["14:20","vierzehn Uhr zwanzig","zwanzig nach zwei"],["17:50","siebzehn Uhr fünfzig","zehn vor sechs"],["18:05","achtzehn Uhr fünf","fünf nach sechs"]]},
 {t: "key", h: "<b>Careful:</b> <i>halb neun</i> is 8:30, not 9:30. German says half <i>to</i> nine."},
 {t: "table", head: ["Word","Meaning","Example"], de: [0], rows: [["um","at (exact time)","um 8 Uhr"],["von ... bis","from ... to","von 9 bis 12 Uhr"],["ab","from (start)","ab 10 Uhr"],["gegen","around","gegen 15 Uhr"],["bis","until","bis 17 Uhr"]]},
 {t: "h", h: "Examples, read aloud"},
 {t: "ex", items: [["Die Besprechung beginnt um halb zehn.","The meeting starts at half past nine."],["Das Büro ist von 8 bis 17 Uhr geöffnet.","The office is open from 8 to 5."],["Ab zwölf Uhr haben wir Mittagspause.","From twelve we have lunch break."],["Ich rufe Sie gegen drei Uhr zurück.","I will call you back around three."],["Der Termin dauert eine Stunde.","The appointment lasts one hour."]]}]},
{title: "Practice: time and prepositions", goal: "Goal: say times without thinking. Write on paper first, then check.", parts: [
 {t: "q", title: "Practice 1: say the time the spoken way", items: ["1. 9:30","2. 7:45","3. 12:15","4. 16:50","5. 13:10"], ans: "1. halb zehn · 2. Viertel vor acht · 3. Viertel nach zwölf · 4. zehn vor fünf · 5. zehn nach eins"},
 {t: "q", title: "Practice 2: um, von ... bis, ab, gegen, bis", items: ["1. Das Büro ist ___ 8 ___ 16 Uhr geöffnet.","2. Die Besprechung beginnt ___ 10 Uhr.","3. ___ 12 Uhr ist Mittagspause.","4. Ich bin ___ 15 Uhr wieder da.","5. Wir arbeiten ___ 17 Uhr."], ans: "1. von ... bis · 2. um · 3. Ab · 4. gegen · 5. bis"},
 {t: "q", title: "Practice 3: say in German", items: ["1. The appointment is at half past two.","2. I have a meeting from 9 to 10.","3. Can we postpone the appointment?","4. I will call you around three."], ans: "1. Der Termin ist um halb drei. · 2. Ich habe von neun bis zehn Uhr eine Besprechung. · 3. Können wir den Termin verschieben? · 4. Ich rufe Sie gegen drei Uhr an."}]},
{title: "Email: move an appointment", goal: "Goal: understand and write the structure of a formal email: Betreff, Anrede, text, Grußformel.", parts: [
 {t: "text", title: "Terminverschiebung", de: "<b>Betreff:</b> Terminverschiebung<br><br>Sehr geehrte Frau Becker,<br><br>leider kann ich den Termin am Dienstag um 10 Uhr nicht wahrnehmen. Ich habe eine Besprechung, die bis 11 Uhr dauert. Könnten wir den Termin auf Mittwoch um 14 Uhr verschieben? Bitte geben Sie mir kurz Bescheid.<br><br>Mit freundlichen Grüßen<br>Daniel Weber", en: "Subject: Moving the appointment. Dear Ms Becker, unfortunately I cannot attend the appointment on Tuesday at 10. I have a meeting that lasts until 11. Could we move the appointment to Wednesday at 14:00? Please let me know briefly. Kind regards, Daniel Weber.", qs: ["1. Welcher Termin ist am Dienstag?","2. Warum kann Herr Weber nicht kommen?","3. Welchen neuen Termin schlägt er vor?"], ans: "1. Der Termin um 10 Uhr. · 2. Er hat eine Besprechung bis 11 Uhr. · 3. Mittwoch um 14 Uhr."},
 {t: "key", h: "<b>Useful reply:</b> Mittwoch um 14 Uhr passt mir gut. Ich bestätige den Termin. (Wednesday at 14:00 suits me. I confirm the appointment.)"}]},
{title: "Read: a day in the office", goal: "Goal: understand a story about a workday in the Präteritum. Follow the steps: listen, read, answer, find the verbs.", parts: [
 {t: "text", title: "Ein Tag im Büro", de: "Gestern begann mein Arbeitstag um acht Uhr. Zuerst las ich meine E-Mails. Um halb zehn hatten wir eine Besprechung mit dem Chef. Sie dauerte fast eine Stunde. Danach rief ich einen Kunden an und vereinbarte einen Termin für Donnerstag. Um zwölf Uhr machten wir Mittagspause. Am Nachmittag schrieb ich einen Bericht und ordnete die Belege. Um fünf Uhr hatte ich endlich Feierabend.", en: "Yesterday my working day began at eight. First I read my emails. At half past nine we had a meeting with the boss. It lasted almost an hour. Afterwards I called a customer and arranged an appointment for Thursday. At twelve we took a lunch break. In the afternoon I wrote a report and sorted the receipts. At five I finally finished work.", qs: ["1. Wann begann der Arbeitstag?","2. Wie lange dauerte die Besprechung?","3. Welchen Termin vereinbarte er?","4. Wann hatte er Feierabend?"], ans: "1. Um acht Uhr. · 2. Fast eine Stunde. · 3. Einen Termin für Donnerstag. · 4. Um fünf Uhr.", note: "New forms: begann (beginnen), las (lesen), rief ... an (anrufen), ordnete (ordnen, to sort). der Beleg means receipt or voucher, a key word in accounting."}]},
{title: "Say it aloud and write", parts: [
 {t: "say", title: "Part A: speak (15 min)", goal: "Press Hear it, then say each sentence 3 times out loud, as fast as the voice.", items: ["Die Besprechung beginnt um halb zehn.","Das Büro ist von acht bis siebzehn Uhr geöffnet.","Ab zwölf Uhr haben wir Mittagspause.","Ich rufe Sie gegen drei Uhr zurück.","Leider kann ich den Termin nicht wahrnehmen.","Könnten wir den Termin verschieben?","Ich bestätige den Termin am Mittwoch um vierzehn Uhr.","Um fünf Uhr hatte ich endlich Feierabend."]},
 {t: "write", title: "Part B: write (15 min), today's homework", goal: "Write a short formal email (5 to 6 sentences) to move an appointment. Use: Betreff, Sehr geehrte/r ..., a reason, a new time, Mit freundlichen Grüßen.", starters: ["Betreff: ...","Sehr geehrter Herr ...,","leider kann ich ... nicht wahrnehmen.","Könnten wir den Termin auf ... verschieben?"], model: "Betreff: Terminverschiebung<br>Sehr geehrter Herr Schulz,<br>leider kann ich den Termin am Montag um 9 Uhr nicht wahrnehmen. Ich muss an diesem Tag früh zum Arzt. Könnten wir den Termin auf Dienstag um 10 Uhr verschieben? Bitte geben Sie mir kurz Bescheid.<br>Mit freundlichen Grüßen<br>Ihr Name"},
 {t: "q", title: "Final check (3 min)", items: ["Without looking above, say in German: 1. The appointment is at half past two. 2. I have a meeting from nine to ten. 3. Can we postpone the appointment? 4. I will call you around three."], ans: "1. Der Termin ist um halb drei. · 2. Ich habe von neun bis zehn Uhr eine Besprechung. · 3. Können wir den Termin verschieben? · 4. Ich rufe Sie gegen drei Uhr an."}]}
]};

/* ================= DAY 35 ================= */
D[35] = {title: "als and wenn: telling childhood stories", level: "Level A2",
intro: "Today you learn to tell a story about the past with als and wenn. These small words are in every B1 and B2 text and in the exam.",
blocks: [
{title: "20 new words", goal: "Goal: say what each word means. Cover the English column and test yourself. Do this 2 times.", parts: [
 {t: "words", rows: [["das Spielzeug","toy"],["der Spielplatz","playground"],["die Ferien","holidays (plural)"],["der Ausflug","trip, outing"],["die Erinnerung","memory"],["das Geschenk","present, gift"],["der Geburtstag","birthday"],["das Fahrrad","bicycle"],["der Streit","argument, quarrel"],["sich erinnern an","to remember"],["vergessen","to forget"],["weinen","to cry"],["streiten","to argue"],["verlieren","to lose"],["gewinnen","to win"],["manchmal","sometimes"],["immer","always"],["nie","never"],["jung","young"],["mutig","brave"]]},
 {t: "p", h: CHK}]},
{title: "als or wenn?", goal: "Goal: choose the right word and put the verb in the right place.", parts: [
 {t: "table", head: ["Situation","Use","Example"], de: [1], rows: [["One single event in the past","als","Als ich acht war, bekam ich ein Fahrrad."],["A period in the past","als","Als wir klein waren, wohnten wir im Dorf."],["Repeated event in the past (whenever)","wenn","Wenn es regnete, blieben wir zu Hause."],["Present or future","wenn","Wenn ich Zeit habe, rufe ich dich an."]]},
 {t: "key", h: "<b>Word order:</b> after als and wenn the verb goes to the <b>end</b> of the clause. If this clause comes first, the next verb stands right after the comma: <i>Als ich klein war, wohnten wir im Dorf.</i>"},
 {t: "h", h: "Examples, read aloud"},
 {t: "ex", items: [["Als ich zehn war, zogen wir um.","When I was ten, we moved."],["Als wir Kinder waren, spielten wir jeden Tag draußen.","When we were children, we played outside every day."],["Immer wenn wir nur ein Spielzeug hatten, gab es Streit.","Whenever we had only one toy, there was an argument."],["Als er mich sah, lachte er.","When he saw me, he laughed."],["Wenn ich müde bin, trinke ich Tee.","When I am tired, I drink tea."]]}]},
{title: "Practice: als and wenn", goal: "Goal: choose and build without looking at the rules. Write on paper first, then check.", parts: [
 {t: "q", title: "Practice 1: als or wenn?", items: ["1. ___ ich zehn war, zogen wir um.","2. ___ ich Zeit habe, besuche ich dich.","3. ___ wir Kinder waren, spielten wir jeden Tag draußen.","4. Immer ___ es regnete, blieben wir zu Hause.","5. ___ ich gestern nach Hause kam, schlief mein Sohn schon.","6. ___ du morgen kommst, bring bitte Brot mit."], ans: "1. Als · 2. Wenn · 3. Als · 4. wenn · 5. Als · 6. Wenn"},
 {t: "q", title: "Practice 2: join two sentences with als", items: ["1. Ich war klein. Ich hatte Angst vor Hunden.","2. Wir wohnten in Berlin. Wir hatten kein Auto.","3. Meine Schwester kam zur Welt. Ich war fünf.","4. Er sah mich. Er lachte."], ans: "1. Als ich klein war, hatte ich Angst vor Hunden. · 2. Als wir in Berlin wohnten, hatten wir kein Auto. · 3. Als meine Schwester zur Welt kam, war ich fünf. · 4. Als er mich sah, lachte er."}]},
{title: "Dialogue: a childhood present", goal: "Goal: understand a spoken conversation. People use the Perfekt in speech, plus war and hatte. You learn the Perfekt in week 2, so today just read it and say it aloud.", parts: [
 {t: "text", de: "Lena: Was war dein schönstes Geschenk als Kind?<br>Murat: Ein Fahrrad. Ich war acht, als ich es zum Geburtstag bekommen habe. Ich habe sofort geübt und bin schon am gleichen Tag gefahren.<br>Lena: Und hast du dich oft mit deinem Bruder gestritten?<br>Murat: Ja, oft! Immer wenn wir nur ein Spielzeug hatten, gab es Streit. Aber wir haben uns schnell wieder vertragen.", en: "Lena: What was your nicest present as a child? Murat: A bicycle. I was eight when I got it for my birthday. I practised right away and rode it the same day. Lena: And did you often argue with your brother? Murat: Yes, often! Whenever we had only one toy, there was an argument. But we made up quickly.", qs: ["1. Wie alt war Murat, als er das Fahrrad bekam?","2. Wann gab es Streit?","3. Was machten die Brüder danach?"], ans: "1. Acht. · 2. Wenn sie nur ein Spielzeug hatten. · 3. Sie haben sich schnell wieder vertragen (they made up)."}]},
{title: "Read: my first day at school", goal: "Goal: understand a written story with als. Follow the steps: listen, read, answer, find the als sentences.", parts: [
 {t: "text", title: "Mein erster Schultag", de: "Als ich sechs Jahre alt war, kam ich in die Schule. Am ersten Tag wachte ich früh auf, weil ich so aufgeregt war. Meine Mutter brachte mich zur Schule und gab mir eine große Schultüte. Als ich in die Klasse kam, sah ich viele fremde Kinder. Ich hatte Angst, aber dann sprach mich ein Junge an. Er hieß Jonas und wurde mein bester Freund. Wenn ich heute an diesen Tag denke, muss ich lächeln.", en: "When I was six years old, I started school. On the first day I woke up early, because I was so excited. My mother took me to school and gave me a big school cone. When I came into the classroom, I saw many strange children. I was afraid, but then a boy spoke to me. His name was Jonas and he became my best friend. When I think about that day today, I have to smile.", qs: ["1. Wie alt war der Erzähler?","2. Warum wachte er früh auf?","3. Wer sprach ihn an?","4. Was muss er heute tun, wenn er an den Tag denkt?"], ans: "1. Sechs Jahre. · 2. Weil er aufgeregt war. · 3. Ein Junge, Jonas. · 4. Er muss lächeln.", note: "New: aufgeregt = excited, ansprechen = to speak to someone, hieß (heißen) = was called, wurde (werden) = became. weil = because, the verb goes to the end, just like with als."}]},
{title: "Say it aloud and write", parts: [
 {t: "say", title: "Part A: speak (15 min)", goal: "Press Hear it, then say each sentence 3 times out loud, as fast as the voice.", items: ["Als ich acht war, bekam ich ein Fahrrad.","Als wir klein waren, wohnten wir im Dorf.","Wenn es regnete, blieben wir zu Hause.","Als er mich sah, lachte er.","Immer wenn wir Streit hatten, vertrugen wir uns schnell.","Als ich in die Klasse kam, hatte ich Angst.","Wenn ich Zeit habe, rufe ich dich an.","Als ich sechs war, kam ich in die Schule."]},
 {t: "write", title: "Part B: write (15 min), today's homework", goal: "Write 8 sentences about your childhood. Start at least 3 sentences with Als ... and use wenn at least once.", starters: ["Als ich klein war, ...","Als ich sechs war, ...","Immer wenn ... , ...","Als ich meinen besten Freund traf, ..."], model: "Als ich klein war, wohnten wir in einer kleinen Stadt. Als ich sechs war, kam ich in die Schule. Am ersten Tag hatte ich Angst, aber dann fand ich eine Freundin. Immer wenn wir Zeit hatten, spielten wir im Park. Als ich zehn war, bekam ich ein Fahrrad. Ich fuhr jeden Tag damit zur Schule. Wenn ich heute daran denke, muss ich lachen. Es war eine schöne Zeit."},
 {t: "q", title: "Final check (3 min)", items: ["Without looking above, say in German: 1. When I was a child, I lived in a village. 2. Whenever it rained, we stayed at home. 3. When he saw me, he laughed. 4. When I have time, I will call you."], ans: "1. Als ich ein Kind war, wohnte ich in einem Dorf. · 2. Immer wenn es regnete, blieben wir zu Hause. · 3. Als er mich sah, lachte er. · 4. Wenn ich Zeit habe, rufe ich dich an."}]}
]};

/* ================= DAY 36 ================= */
D[36] = {title: "Week 1 review and test", level: "Level A2",
intro: "Today you test everything from Days 31 to 35. Do not look back while you answer. Count your points at the end of block 3. Where you lose points, repeat that day.",
blocks: [
{title: "Word check", goal: "Goal: check the 20 most important words of the week. Cover the English column. Mark every word you do not know and say it 5 times.", parts: [
 {t: "words", rows: [["damals","back then"],["endlich","finally"],["plötzlich","suddenly"],["der Bahnhof","train station"],["die Kindheit","childhood"],["das Dorf","village"],["erzählen","to tell"],["besuchen","to visit"],["der Beruf","profession"],["heiraten","to marry"],["umziehen","to move (house)"],["bleiben","to stay"],["der Termin","appointment"],["die Besprechung","meeting"],["verschieben","to postpone"],["pünktlich","on time"],["die Erinnerung","memory"],["der Streit","argument"],["sich erinnern an","to remember"],["vergessen","to forget"]]},
 {t: "p", h: CHK}]},
{title: "Verb forms check", goal: "Goal: write the Präteritum (ich / er form) of 15 verbs. Write on paper, then check. Count your correct answers (15 points).", parts: [
 {t: "key", h: "<b>Remember:</b> sein/haben/modals: war, hatte, konnte ... Regular: stem + -te. Irregular: new stem, no -te (ging, kam, sah ...). Mixed: bringen, denken, wissen (brachte, dachte, wusste)."},
 {t: "q", title: "Write the Präteritum (ich / er)", items: ["1. sein · 2. haben · 3. können · 4. müssen · 5. wollen","6. gehen · 7. kommen · 8. sehen · 9. fahren · 10. finden","11. arbeiten · 12. wohnen · 13. spielen · 14. wissen · 15. bringen"], ans: "1. war · 2. hatte · 3. konnte · 4. musste · 5. wollte · 6. ging · 7. kam · 8. sah · 9. fuhr · 10. fand · 11. arbeitete · 12. wohnte · 13. spielte · 14. wusste · 15. brachte"}]},
{title: "Mixed test", goal: "Goal: use everything in sentences. 23 points. Write on paper, check, then count your points together with block 2 (38 in total).", parts: [
 {t: "q", title: "Test A: fill the gap (12 points)", items: ["1. Gestern ___ ich sehr müde. (sein)","2. Wir ___ keine Zeit. (haben)","3. Ich ___ gestern lange arbeiten. (müssen)","4. Mein Großvater ___ in einem Dorf. (wohnen)","5. Sie ___ mit dem Zug nach Hamburg. (fahren)","6. Er ___ mir eine E-Mail. (schreiben)","7. Wir ___ ins Kino gehen, aber es war zu spät. (wollen)","8. Ihr ___ lange im Büro. (bleiben)","9. Die Kinder ___ im Garten. (spielen)","10. Ich ___ nicht, wo er wohnte. (wissen)","11. Sie ___ ihre Tante am Bahnhof. (treffen)","12. Du ___ gestern nicht kommen. (können)"], ans: "1. war · 2. hatten · 3. musste · 4. wohnte · 5. fuhr · 6. schrieb · 7. wollten · 8. bliebt · 9. spielten · 10. wusste · 11. traf · 12. konntest"},
 {t: "q", title: "Test B: als or wenn? (6 points)", items: ["1. ___ ich klein war, hatte ich ein Fahrrad.","2. ___ ich müde bin, trinke ich Tee.","3. ___ wir ankamen, regnete es.","4. Immer ___ er Zeit hatte, besuchte er Oma.","5. ___ du morgen Zeit hast, ruf mich an.","6. ___ ich in Berlin wohnte, hatte ich kein Auto."], ans: "1. Als · 2. Wenn · 3. Als · 4. wenn · 5. Wenn · 6. Als"},
 {t: "q", title: "Test C: what is natural when you speak to a friend? (5 points)", items: ["1. Ich (arbeitete / habe gearbeitet) gestern.","2. Ich (war / bin gewesen) gestern müde.","3. Wir (hatten / haben gehabt) viel Zeit.","4. Sie (kaufte / hat gekauft) ein Brot.","5. Ich (musste / habe gemusst) lange warten."], ans: "1. habe gearbeitet · 2. war · 3. hatten · 4. hat gekauft · 5. musste"},
 {t: "key", h: "<b>Your score (38 points):</b> 34 or more: move on. 30 to 33: repeat only the part where you lost points. Below 30: repeat the day that matches. sein, haben, modals = Day 31. Regular verbs = Day 32. Irregular verbs = Day 33. Time and appointments = Day 34. als and wenn = Day 35."}]},
{title: "Phone call and reading", goal: "Goal: understand a short business phone call. Listen first, then read, then answer.", parts: [
 {t: "text", title: "Ein Anruf im Büro", de: "Frau Keller: Firma Bauer, Keller, guten Tag.<br>Herr Aydin: Guten Tag, hier ist Aydin. Ich möchte gern einen Termin mit Herrn Bauer vereinbaren.<br>Frau Keller: Gern. Wann hätten Sie Zeit?<br>Herr Aydin: Am Donnerstag, am liebsten vormittags.<br>Frau Keller: Donnerstag um 10 Uhr würde gehen. Passt Ihnen das?<br>Herr Aydin: Ja, das passt gut. Vielen Dank.<br>Frau Keller: Gern geschehen. Auf Wiederhören.", en: "Ms Keller: Company Bauer, Keller speaking, good day. Mr Aydin: Good day, this is Aydin. I would like to arrange an appointment with Mr Bauer. Ms Keller: Gladly. When would you have time? Mr Aydin: On Thursday, preferably in the morning. Ms Keller: Thursday at 10 would work. Does that suit you? Mr Aydin: Yes, that suits me well. Thank you. Ms Keller: You're welcome. Goodbye (on the phone).", qs: ["1. Wer ruft an?","2. Was möchte er?","3. Wann ist der Termin?","4. Wie sagt man am Telefon Goodbye?"], ans: "1. Herr Aydin. · 2. Einen Termin mit Herrn Bauer vereinbaren. · 3. Am Donnerstag um 10 Uhr. · 4. Auf Wiederhören.", note: "Polite chunks to learn by heart: Wann hätten Sie Zeit? / Das würde gehen. / Passt Ihnen das? You learn why they look like this in week 10."}]},
{title: "Dictation", goal: "Goal: write what you hear. Press the button up to 3 times, write on paper, then open the text and correct yourself.", parts: [
 {t: "text", title: "Diktat", hide: true, de: "Gestern war ich im Büro. Ich musste lange arbeiten. Als ich nach Hause kam, war ich sehr müde. Meine Mutter kochte Suppe. Wir aßen zusammen und sprachen über den Tag.", en: "Yesterday I was at the office. I had to work a long time. When I came home, I was very tired. My mother cooked soup. We ate together and talked about the day.", note: "Count your mistakes. 0 to 2: very good. 3 to 5: listen again tomorrow. More than 5: repeat Days 31 and 33."},
 {t: "p", h: "Then read the text aloud twice, as fast as the voice."}]},
{title: "Speak and self-check", parts: [
 {t: "say", title: "Part A: retell your week (15 min)", goal: "Say each sentence aloud 3 times, then change it so it is true for you.", items: ["Gestern war ich im Büro.","Ich musste lange arbeiten.","Als ich nach Hause kam, war ich müde.","Meine Mutter kochte, und wir aßen zusammen.","Am Wochenende besuchte ich meine Oma.","Sie erzählte mir von früher.","Damals hatten wir wenig Geld, aber wir waren glücklich.","Der Termin ist um halb drei."]},
 {t: "write", title: "Part B: write (10 min)", goal: "Write 10 sentences: My week. Use war, hatte, a modal verb, a regular verb, an irregular verb, als and one time with um, von ... bis or gegen.", model: "Am Montag war ich im Büro. Ich musste viel arbeiten und hatte kaum Zeit. Um halb eins machte ich Mittagspause. Am Dienstag besuchte ich meine Tante. Sie erzählte mir von früher. Als ich nach Hause kam, regnete es. Am Mittwoch fuhr ich mit dem Bus zur Arbeit. Ich traf einen Kollegen und wir sprachen über den Termin. Von drei bis vier Uhr hatten wir eine Besprechung. Am Abend war ich müde, aber glücklich."},
 {t: "list", title: "Self-check: tick it in your head", items: ["I can say what I was, had, could, had to and wanted to do.","I can tell a short story in the Präteritum with regular and irregular verbs.","I can tell the time and make or move an appointment.","I can use als for a past event and wenn for a repeated one.","I can write a short formal email to move an appointment."]}]}
]};

/* ================= DAY 37 ================= */
D[37] = {title: "Speaking and writing: family and work", level: "Level A2",
intro: "Today you produce German, you do not only read it. You learn 20 useful phrases, speak with a family conversation, answer interview questions aloud and write two texts: one to family and one to a workplace.",
blocks: [
{title: "20 useful phrases", goal: "Goal: say each phrase aloud 3 times. Then cover the English and check yourself. These are real phrases for family and work.", parts: [
 {t: "words", rows: [["Wie war dein Tag?","How was your day?"],["Das tut mir leid.","I am sorry (about that)."],["Das freut mich sehr.","I am very glad."],["Entschuldigung, ich habe mich verspätet.","Sorry, I am late."],["Kannst du mir bitte helfen?","Can you help me please?"],["Hast du Lust, ins Kino zu gehen?","Do you feel like going to the cinema?"],["Ich habe leider keine Zeit.","Unfortunately I have no time."],["Ich melde mich später.","I will get back to you later."],["Bis bald!","See you soon!"],["Gern geschehen.","You are welcome."],["Sehr geehrte Frau Becker,","Dear Ms Becker, (formal)"],["Mit freundlichen Grüßen","Kind regards"],["Vielen Dank für Ihre Nachricht.","Thank you for your message."],["Ich möchte einen Termin vereinbaren.","I would like to arrange an appointment."],["Leider kann ich den Termin nicht wahrnehmen.","Unfortunately I cannot attend the appointment."],["Könnten wir den Termin verschieben?","Could we postpone the appointment?"],["Bitte geben Sie mir kurz Bescheid.","Please let me know briefly."],["Ich bestätige den Termin.","I confirm the appointment."],["Ich freue mich auf Ihre Antwort.","I look forward to your reply."],["Auf Wiederhören.","Goodbye (on the phone)."]]},
 {t: "p", h: "The first 10 are for family and friends (du). The last 10 are formal (Sie) and for work."}]},
{title: "Family conversation", goal: "Goal: read and say a real family phone call. Spoken German uses war, hatte, modals and the Perfekt.", parts: [
 {t: "text", de: "Mutter: Hallo, Daniel! Wie war dein Tag?<br>Daniel: Hallo, Mama. Ich war lange im Büro. Ich musste viel arbeiten. Und bei dir?<br>Mutter: Ich habe Oma besucht. Sie hat uns zum Essen am Sonntag eingeladen.<br>Daniel: Das freut mich! Um wie viel Uhr?<br>Mutter: Um halb eins. Kannst du pünktlich sein?<br>Daniel: Ja, klar. Soll ich etwas mitbringen?<br>Mutter: Bring bitte Blumen mit.<br>Daniel: Mache ich. Bis Sonntag!", en: "Mother: Hello, Daniel! How was your day? Daniel: Hello, Mum. I was at the office a long time. I had to work a lot. And you? Mother: I visited Grandma. She invited us for lunch on Sunday. Daniel: I am glad! At what time? Mother: At half past twelve. Can you be on time? Daniel: Yes, sure. Should I bring something? Mother: Please bring flowers. Daniel: Will do. See you Sunday!", qs: ["1. Wie war Daniels Tag?","2. Wen hat die Mutter besucht?","3. Um wie viel Uhr ist das Essen?","4. Was soll Daniel mitbringen?"], ans: "1. Er war lange im Büro und musste viel arbeiten. · 2. Die Oma. · 3. Um halb eins. · 4. Blumen."},
 {t: "p", h: "Read the dialogue aloud twice. Then cover Daniel's lines and answer the mother's questions with your own true answers."}]},
{title: "Speaking questions", goal: "Goal: answer 10 questions aloud, each in 2 to 4 sentences. Pattern: answer + reason + one example. Record yourself if you can.", parts: [
 {t: "list", title: "Questions (answer aloud)", items: ["1. Wo sind Sie aufgewachsen?","2. Was haben Sie als Kind gern gemacht?","3. Wie viele Personen gibt es in Ihrer Familie?","4. Was haben Sie gestern gemacht?","5. Wie sieht ein normaler Tag bei Ihnen aus?","6. Warum möchten Sie in Deutschland arbeiten?","7. Warum interessieren Sie sich für Buchhaltung?","8. Was können Sie gut?","9. Was war schwierig, als Sie Deutsch gelernt haben?","10. Was möchten Sie in fünf Jahren machen?"]},
 {t: "key", h: "<b>Model answers for 1 and 7:</b><br>1. Ich bin in einer kleinen Stadt aufgewachsen. Als Kind habe ich viel draußen gespielt. Meine Familie hat dort noch ein Haus.<br>7. Ich interessiere mich für Buchhaltung, weil ich gern mit Zahlen arbeite. Außerdem finde ich es wichtig, genau und ordentlich zu sein."}]},
{title: "Write to your family", goal: "Goal: write a friendly message in correct standard German to a family member. About 60 to 80 words.", parts: [
 {t: "write", goal: "Write a message to a family member (Oma, Mutter, Onkel). Thank them for an invitation, tell them what you did last weekend, and tell them one thing from your childhood with als. Use war, hatte and a modal verb.", starters: ["Liebe Oma, / Lieber Onkel,","vielen Dank für ...","Letztes Wochenende war ich ...","Als ich klein war, ...","Viele Grüße"], model: "Liebe Oma,<br>vielen Dank für die Einladung am Sonntag! Ich komme gern und bringe Blumen mit. Letztes Wochenende war ich leider sehr müde, denn ich musste viel arbeiten. Als ich ein Kind war, habe ich bei dir immer deinen Kuchen gegessen. Ich freue mich schon darauf.<br>Viele Grüße<br>Daniel"}]},
{title: "Write a work email", goal: "Goal: write a short formal email. About 60 to 80 words.", parts: [
 {t: "text", title: "Model", de: "<b>Betreff:</b> Terminbestätigung<br><br>Sehr geehrte Frau Becker,<br><br>vielen Dank für Ihre Nachricht. Ich bestätige den Termin am Mittwoch um 14 Uhr. Könnten Sie mir bitte noch die Adresse schicken? Ich freue mich auf das Gespräch.<br><br>Mit freundlichen Grüßen<br>Daniel Weber", en: "Subject: Confirmation of appointment. Dear Ms Becker, thank you for your message. I confirm the appointment on Wednesday at 14:00. Could you please also send me the address? I look forward to the conversation. Kind regards, Daniel Weber."},
 {t: "write", goal: "Write your own email: confirm an appointment, ask one question, say thank you. Check: Betreff, Sehr geehrte/r ..., 3 content points, Mit freundlichen Grüßen, your name.", starters: ["Betreff: ...","vielen Dank für ...","Ich bestätige ...","Könnten Sie mir bitte ...?"]}]},
{title: "Check and record", goal: "Goal: correct your own texts and speak for one minute without stopping.", parts: [
 {t: "list", title: "Check your two texts for these 6 points", items: ["The verb is in position 2 in main clauses.","ich and er/sie/es have the same Präteritum form (war, hatte, konnte).","Nouns have a capital letter and the right article.","After als and weil the verb is at the end.","Formal email: Sie, Betreff, greeting and closing are all there.","Every sentence ends with a full stop or a question mark."]},
 {t: "list", title: "Record yourself for 1 minute: Mein Alltag", items: ["Wann stehe ich auf und was mache ich am Morgen?","Wo arbeite oder lerne ich und von wann bis wann?","Was habe ich gestern gemacht?","Was möchte ich am Wochenende machen?"]},
 {t: "p", h: "Listen to your recording once. Write down 3 words you were not sure about, and say them 5 times each."}]}
]};

/* ================= DAY 38 ================= */
D[38] = {title: "Perfekt with haben: weekend and invitations", level: "Level A2",
intro: "This is the start of week 2. The Perfekt is the main past tense for speaking. Today you learn the Perfekt of regular verbs with haben: haben + Partizip II.",
blocks: [
{title: "20 new words", goal: "Goal: say what each word means. Cover the English column and test yourself. Do this 2 times.", parts: [
 {t: "words", rows: [["das Wochenende","weekend"],["die Einladung","invitation"],["die Party","party"],["der Kuchen","cake"],["das Konzert","concert"],["der Spaziergang","walk"],["der Besuch","visit"],["der Gast","guest"],["einladen","to invite"],["feiern","to celebrate"],["tanzen","to dance"],["planen","to plan"],["zusagen","to accept (an invitation)"],["schenken","to give as a present"],["organisieren","to organise"],["bezahlen","to pay"],["reservieren","to reserve"],["abholen","to pick up"],["mitbringen","to bring along"],["gemütlich","cosy"]]},
 {t: "p", h: CHK}]},
{title: "Perfekt with haben", goal: "Goal: build the Perfekt of regular verbs: haben + Partizip II.", parts: [
 {t: "key", h: "<b>Rule:</b> haben (position 2) + Partizip II (at the end). Regular Partizip II: <b>ge- + stem + -t</b>. Example: machen, gemacht. Ich <b>habe</b> am Samstag eine Party <b>gemacht</b>."},
 {t: "table", head: ["Infinitive","Partizip II","Note"], de: [1], rows: [["machen","gemacht","ge- + stem + -t"],["spielen","gespielt",""],["kaufen","gekauft",""],["wohnen","gewohnt",""],["arbeiten","gearbeitet","stem ends in -t: add -et"],["tanzen","getanzt",""],["besuchen","besucht","no ge- after be-, ver-, er-"],["bezahlen","bezahlt","no ge-"],["organisieren","organisiert","no ge- after -ieren"],["reservieren","reserviert","no ge-"],["abholen","abgeholt","separable: ge goes in the middle"],["einkaufen","eingekauft","separable"]]},
 {t: "h", h: "Examples, read aloud"},
 {t: "ex", items: [["Wir haben am Samstag bei Lena gefeiert.","We celebrated at Lena's on Saturday."],["Hast du den Kuchen gekauft?","Did you buy the cake?"],["Ich habe die Gäste um acht Uhr abgeholt.","I picked up the guests at eight."],["Sie haben einen Tisch reserviert.","They reserved a table."],["Wir haben den ganzen Abend getanzt.","We danced the whole evening."]]}]},
{title: "Practice: Partizip II", goal: "Goal: build the forms without looking at the table. Write on paper first, then check.", parts: [
 {t: "q", title: "Practice 1: write the Partizip II", items: ["1. machen · 2. spielen · 3. kaufen · 4. wohnen · 5. arbeiten · 6. lernen","7. besuchen · 8. bezahlen · 9. organisieren · 10. abholen · 11. einkaufen · 12. planen"], ans: "1. gemacht · 2. gespielt · 3. gekauft · 4. gewohnt · 5. gearbeitet · 6. gelernt · 7. besucht · 8. bezahlt · 9. organisiert · 10. abgeholt · 11. eingekauft · 12. geplant"},
 {t: "q", title: "Practice 2: fill the Perfekt", items: ["1. Ich ___ gestern Kuchen ___. (kaufen)","2. Wir ___ am Sonntag einen Spaziergang ___. (machen)","3. ___ du die Party ___? (organisieren)","4. Meine Eltern ___ einen Tisch ___. (reservieren)","5. Ich ___ meinen Bruder am Bahnhof ___. (abholen)","6. Er ___ die Rechnung ___. (bezahlen)","7. Ihr ___ den ganzen Abend ___. (tanzen)","8. Wir ___ lange ___. (planen)"], ans: "1. habe ... gekauft · 2. haben ... gemacht · 3. Hast ... organisiert · 4. haben ... reserviert · 5. habe ... abgeholt · 6. hat ... bezahlt · 7. habt ... getanzt · 8. haben ... geplant"},
 {t: "q", title: "Practice 3: Präteritum to Perfekt (speaking style)", items: ["1. Ich kaufte ein Geschenk.","2. Sie lernte Deutsch.","3. Wir feierten Geburtstag.","4. Er besuchte seine Tante."], ans: "1. Ich habe ein Geschenk gekauft. · 2. Sie hat Deutsch gelernt. · 3. Wir haben Geburtstag gefeiert. · 4. Er hat seine Tante besucht."}]},
{title: "Chat: a birthday invitation", goal: "Goal: understand a written chat between friends in standard German. Note: eingeladen is an irregular Partizip II, you learn those next.", parts: [
 {t: "text", de: "Lena: Hallo Anna, ich habe am Samstag Geburtstag und möchte feiern. Hast du Lust zu kommen?<br>Anna: Hallo Lena, vielen Dank für die Einladung! Wann und wo feiert ihr?<br>Lena: Um 18 Uhr bei mir zu Hause. Ich habe schon alle Gäste eingeladen und einen Kuchen bestellt.<br>Anna: Das klingt super! Ich komme gern. Soll ich etwas mitbringen?<br>Lena: Ja, gern Getränke. Danke dir!", en: "Lena: Hello Anna, I have my birthday on Saturday and want to celebrate. Do you feel like coming? Anna: Hello Lena, thank you for the invitation! When and where are you celebrating? Lena: At 18:00 at my place. I have already invited all the guests and ordered a cake. Anna: That sounds great! I am happy to come. Should I bring something? Lena: Yes, drinks please. Thank you!", qs: ["1. Wann hat Lena Geburtstag?","2. Wo feiert sie?","3. Was hat Lena schon gemacht?","4. Was soll Anna mitbringen?"], ans: "1. Am Samstag. · 2. Bei ihr zu Hause, um 18 Uhr. · 3. Sie hat alle Gäste eingeladen und einen Kuchen bestellt. · 4. Getränke."}]},
{title: "Read: my weekend", goal: "Goal: understand a spoken-style story in the Perfekt. Follow the steps: listen, read, answer, find the Perfekt forms.", parts: [
 {t: "text", title: "Mein Wochenende", de: "Am Samstag habe ich zuerst Kuchen gekauft und die Wohnung aufgeräumt. Dann habe ich meine Freundin abgeholt. Wir haben bei meiner Mutter gekocht und viel gelacht. Am Abend haben wir ein Konzert besucht. Es hat zwei Stunden gedauert. Am Sonntag habe ich zu Hause gearbeitet und Deutsch gelernt.", en: "On Saturday I first bought cake and tidied the flat. Then I picked up my friend. We cooked at my mother's and laughed a lot. In the evening we went to a concert. It lasted two hours. On Sunday I worked at home and learned German.", qs: ["1. Was hat die Person zuerst gemacht?","2. Wen hat sie abgeholt?","3. Was haben sie am Abend besucht?","4. Wie lange hat das Konzert gedauert?"], ans: "1. Sie hat Kuchen gekauft und die Wohnung aufgeräumt. · 2. Ihre Freundin. · 3. Ein Konzert. · 4. Zwei Stunden.", note: "Find all Perfekt forms: gekauft, aufgeräumt, abgeholt, gekocht, gelacht, besucht, gedauert, gearbeitet, gelernt. aufräumen means to tidy up."}]},
{title: "Say it aloud and write", parts: [
 {t: "say", title: "Part A: speak (15 min)", goal: "Press Hear it, then say each sentence 3 times out loud, as fast as the voice.", items: ["Ich habe gestern Kuchen gekauft.","Wir haben am Samstag gefeiert.","Hast du die Party organisiert?","Sie haben einen Tisch reserviert.","Ich habe meinen Bruder abgeholt.","Er hat die Rechnung bezahlt.","Wir haben den ganzen Abend getanzt.","Ich habe am Sonntag Deutsch gelernt."]},
 {t: "write", title: "Part B: write (15 min), today's homework", goal: "Write 8 sentences about last weekend in the Perfekt. Use only regular verbs with haben (machen, spielen, kaufen, kochen, besuchen, lernen ...). Use one separable verb (abholen, einkaufen, aufräumen).", starters: ["Am Samstag habe ich ...","Dann haben wir ...","Am Abend habe ich ...","Am Sonntag habe ich ..."], model: "Am Samstag habe ich eingekauft und die Wohnung aufgeräumt. Dann habe ich meine Schwester besucht. Wir haben Tee getrunken und viel gelacht. Am Abend habe ich Deutsch gelernt. Am Sonntag habe ich lange gearbeitet. Danach habe ich Suppe gekocht. Ich habe nicht viel gemacht, aber es war ein schönes Wochenende."},
 {t: "q", title: "Final check (3 min)", items: ["Without looking above, say in German: 1. I bought a cake. 2. We celebrated. 3. Did you pay the bill? 4. He picked up the guests. 5. They danced the whole evening."], ans: "1. Ich habe einen Kuchen gekauft. · 2. Wir haben gefeiert. · 3. Hast du die Rechnung bezahlt? · 4. Er hat die Gäste abgeholt. · 5. Sie haben den ganzen Abend getanzt."}]}
]};
})();
